-- A. 9_1 structure: rows per district-day, columns, newest date; monthly columns constant within a month?
SELECT column_name, data_type FROM information_schema.columns WHERE table_name='9_1_hydrological_station_master' ORDER BY ordinal_position;;
SELECT count(*) n, count(DISTINCT (district_name, date)) nd, min(date), max(date), count(DISTINCT district_name) districts FROM "9_1_hydrological_station_master";;
SELECT district_name, year, month, count(DISTINCT stage_height) nd_stage, count(DISTINCT suspended_sediment_concentration) nd_ssc, count(DISTINCT flow_velocity) nd_vel, count(DISTINCT daily_sediment_load_t_day) nd_load, count(*) n FROM "9_1_hydrological_station_master" WHERE district_name='Alfred Nzo' AND year=2026 AND month IN (7,8) GROUP BY 1,2,3;;
-- B. KPIs Aug 2026: national flow (sum of district monthly means / 86400), stage (area-weighted monthly value), SSC (area-weighted), high / low status counts (district Aug 2026 mean flow vs its p90 / p10 of monthly means 2000-2025)
WITH {W}, m AS (SELECT w.code, w.area, date_trunc('month', date)::date mth, avg(daily_mean_flow)/86400 q, max(stage_height) stage, max(suspended_sediment_concentration) ssc, max(flow_velocity) vel, avg(daily_sediment_load_t_day) load FROM "9_1_hydrological_station_master" t JOIN w ON lower(w.name)=lower(t.district_name) WHERE date <= '2026-08-31' GROUP BY 1,2,3),
pc AS (SELECT code, percentile_cont(0.9) WITHIN GROUP (ORDER BY q) p90, percentile_cont(0.1) WITHIN GROUP (ORDER BY q) p10 FROM m WHERE extract(year from mth) BETWEEN 2000 AND 2025 GROUP BY 1),
cur AS (SELECT * FROM m WHERE mth='2026-08-01')
SELECT round(sum(cur.q)::numeric,1) flow, round((sum(cur.area*cur.stage)/sum(cur.area))::numeric,3) stage, round((sum(cur.area*cur.ssc)/sum(cur.area))::numeric,1) ssc, round((sum(cur.area*cur.load)/sum(cur.area))::numeric,3) load_wmean, round(sum(cur.load)::numeric,1) load_sum, round((sum(cur.area*cur.vel)/sum(cur.area))::numeric,3) vel,
 count(*) FILTER (WHERE cur.q > pc.p90) high, count(*) FILTER (WHERE cur.q < pc.p10) low, count(*) n,
 (SELECT string_agg(code||':'||round(q::numeric,1)||'/'||round(stage::numeric,3)||'/'||round(ssc::numeric,0)||'/'||round(vel::numeric,3), ' ' ORDER BY code) FROM cur WHERE code IN ('CPT','DC34','DC44','DC14','DC10')) d_flow_stage_ssc_vel FROM cur JOIN pc USING (code);;
-- C. national daily flow on 2025-09-25 and 2026-09-24; Sep 2025 monthly mean (full month vs 25-30 Sep); Oct 2025; long-term Sep / Aug / Jan means 2000-2025; FDC percentiles; Q10 of national monthly flow 2000-01..2026-08
WITH {W}, f AS (SELECT date d, sum(daily_mean_flow)/86400 q, count(*) n FROM "9_1_hydrological_station_master" t JOIN w ON lower(w.name)=lower(t.district_name) GROUP BY 1),
mm AS (SELECT date_trunc('month', d)::date mth, avg(q) q FROM f WHERE d <= '2026-08-31' GROUP BY 1)
SELECT (SELECT round(q::numeric,1) FROM f WHERE d='2025-09-25') d1, (SELECT round(q::numeric,1) FROM f WHERE d='2026-09-24') d2, (SELECT round(avg(q)::numeric,2) FROM f WHERE d BETWEEN '2025-09-01' AND '2025-09-30') sep25_full, (SELECT round(avg(q)::numeric,2) FROM f WHERE d BETWEEN '2025-09-25' AND '2025-09-30') sep25_25to30,
 (SELECT round(avg(q)::numeric,2) FROM f WHERE d BETWEEN '2025-10-01' AND '2025-10-31') oct25, (SELECT round(q::numeric,2) FROM mm WHERE mth='2026-08-01') aug26, (SELECT round(q::numeric,2) FROM mm WHERE mth='2026-01-01') jan26, (SELECT round(q::numeric,2) FROM mm WHERE mth='2025-01-01') jan25,
 (SELECT round(avg(q)::numeric,2) FROM mm WHERE extract(month from mth)=9 AND extract(year from mth) BETWEEN 2000 AND 2025) lt_sep, (SELECT round(avg(q)::numeric,2) FROM mm WHERE extract(month from mth)=8 AND extract(year from mth) BETWEEN 2000 AND 2025) lt_aug, (SELECT round(avg(q)::numeric,2) FROM mm WHERE extract(month from mth)=1 AND extract(year from mth) BETWEEN 2000 AND 2025) lt_jan, (SELECT round(avg(q)::numeric,2) FROM mm WHERE extract(month from mth)=12 AND extract(year from mth) BETWEEN 2000 AND 2025) lt_dec,
 (SELECT min(n) FROM f) min_d, (SELECT round(max(q)::numeric,3) FROM f WHERE d BETWEEN '2025-09-25' AND '2026-09-24') fdc_last_max, (SELECT round(min(q)::numeric,3) FROM f WHERE d BETWEEN '2025-09-25' AND '2026-09-24') fdc_last_min, (SELECT round(max(q)::numeric,2) FROM f WHERE d BETWEEN '2000-01-01' AND '2025-12-31') fdc_lt_max,
 (SELECT round(percentile_cont(0.9) WITHIN GROUP (ORDER BY q)::numeric,1) FROM mm WHERE mth BETWEEN '2000-01-01' AND '2026-08-01') q10_monthly,
 (SELECT round(avg(q)::numeric,1) FROM mm WHERE mth BETWEEN '2025-09-01' AND '2026-08-01') stat_cur12, (SELECT round(avg(q)::numeric,1) FROM mm WHERE extract(year from mth) BETWEEN 2000 AND 2025) stat_clim;;
-- C2. flow anomaly series: monthly national flow vs the 2000-2025 same-month mean (Sep 2025, Oct 2025, Aug 2026) and the annual-mean Sen's slope x10
WITH {W}, f AS (SELECT date d, sum(daily_mean_flow)/86400 q FROM "9_1_hydrological_station_master" t JOIN w ON lower(w.name)=lower(t.district_name) GROUP BY 1),
mm AS (SELECT date_trunc('month', d)::date mth, avg(q) q FROM f WHERE d <= '2026-08-31' GROUP BY 1),
n AS (SELECT extract(month from mth) mo, avg(q) n FROM mm WHERE extract(year from mth) BETWEEN 2000 AND 2025 GROUP BY 1),
y AS (SELECT extract(year from mth)::int yr, avg(q) v FROM mm WHERE extract(year from mth) BETWEEN 2000 AND 2025 GROUP BY 1)
SELECT (SELECT string_agg(to_char(mth,'YYYY-MM')||':'||round(((q-n.n)/n.n*100)::numeric,1), ' ' ORDER BY mth) FROM mm JOIN n ON n.mo=extract(month from mm.mth) WHERE mth IN ('2025-09-01','2025-10-01','2026-08-01')) anomalies,
 (SELECT round((percentile_cont(0.5) WITHIN GROUP (ORDER BY (b.v-a.v)/(b.yr-a.yr)) * 10)::numeric,2) FROM y a JOIN y b ON b.yr > a.yr) sen10_discharge;;
-- D. statistics rows for stage / velocity / SSC / load: current = mean of the last 12 monthly scope values (Sep 2025-Aug 2026), climatology = mean of all months 2000-2025, Sen's slope of annual means
WITH {W}, m AS (SELECT w.code, w.area, date_trunc('month', date)::date mth, max(stage_height) stage, max(suspended_sediment_concentration) ssc, max(flow_velocity) vel, avg(daily_sediment_load_t_day) load FROM "9_1_hydrological_station_master" t JOIN w ON lower(w.name)=lower(t.district_name) WHERE date <= '2026-08-31' GROUP BY 1,2,3),
s AS (SELECT mth, sum(area*stage)/sum(area) stage, sum(area*ssc)/sum(area) ssc, sum(area*vel)/sum(area) vel, sum(area*load)/sum(area) load, sum(load) load_sum FROM m GROUP BY 1),
y AS (SELECT extract(year from mth)::int yr, avg(stage) stage, avg(ssc) ssc, avg(vel) vel, avg(load) load FROM s WHERE extract(year from mth) BETWEEN 2000 AND 2025 GROUP BY 1)
SELECT round(avg(stage) FILTER (WHERE mth BETWEEN '2025-09-01' AND '2026-08-01')::numeric,3) stage_cur, round(avg(stage) FILTER (WHERE extract(year from mth) BETWEEN 2000 AND 2025)::numeric,3) stage_clim,
 round(avg(vel) FILTER (WHERE mth BETWEEN '2025-09-01' AND '2026-08-01')::numeric,3) vel_cur, round(avg(vel) FILTER (WHERE extract(year from mth) BETWEEN 2000 AND 2025)::numeric,3) vel_clim,
 round(avg(ssc) FILTER (WHERE mth BETWEEN '2025-09-01' AND '2026-08-01')::numeric,1) ssc_cur, round(avg(ssc) FILTER (WHERE extract(year from mth) BETWEEN 2000 AND 2025)::numeric,1) ssc_clim,
 round(avg(load) FILTER (WHERE mth BETWEEN '2025-09-01' AND '2026-08-01')::numeric,1) load_cur_wmean, round(avg(load) FILTER (WHERE extract(year from mth) BETWEEN 2000 AND 2025)::numeric,1) load_clim_wmean,
 round(avg(load_sum) FILTER (WHERE mth BETWEEN '2025-09-01' AND '2026-08-01')::numeric,1) load_cur_sum, round(avg(load_sum) FILTER (WHERE extract(year from mth) BETWEEN 2000 AND 2025)::numeric,1) load_clim_sum,
 (SELECT round((percentile_cont(0.5) WITHIN GROUP (ORDER BY (b.stage-a.stage)/(b.yr-a.yr)) * 10)::numeric,4) FROM y a JOIN y b ON b.yr > a.yr) stage_sen,
 (SELECT round((percentile_cont(0.5) WITHIN GROUP (ORDER BY (b.ssc-a.ssc)/(b.yr-a.yr)) * 10)::numeric,2) FROM y a JOIN y b ON b.yr > a.yr) ssc_sen,
 (SELECT string_agg(to_char(mth,'YYYY-MM')||':'||round(stage::numeric,3)||'/'||round(ssc::numeric,3)||'/'||round(load::numeric,3), ' ' ORDER BY mth) FROM s WHERE mth IN ('2025-09-01','2026-08-01')) series_stage_ssc_load FROM s;;
-- E. maps Aug 2026: district flow (m3/s), flow anomaly vs the district's Aug mean 2000-2025 (%), top districts and the change vs Aug 2025
WITH {W}, m AS (SELECT w.code, date_trunc('month', date)::date mth, avg(daily_mean_flow)/86400 q FROM "9_1_hydrological_station_master" t JOIN w ON lower(w.name)=lower(t.district_name) WHERE date <= '2026-08-31' GROUP BY 1,2),
n AS (SELECT code, avg(q) n FROM m WHERE extract(month from mth)=8 AND extract(year from mth) BETWEEN 2000 AND 2025 GROUP BY 1)
SELECT m.code, round(m.q::numeric,1) aug26, round(((m.q-n.n)/n.n*100)::numeric,0) anom_pct, round((m.q - (SELECT q FROM m p WHERE p.code=m.code AND p.mth='2025-08-01'))::numeric,1) vs_last_year FROM m JOIN n USING (code) WHERE mth='2026-08-01' AND m.code IN ('CPT','DC34','DC44','DC14','DC10','BUF','NMA','DC8') ORDER BY 2 DESC;;
-- F. 9_2 entity attributes for Alfred Nzo and the 9_2 structure
SELECT column_name, data_type FROM information_schema.columns WHERE table_name='9_2_catchment_characteristics_master' ORDER BY ordinal_position;;
